    const session = teamsSessionKey({
        source: input.sessionKey,
        identity: runtime.options.continuation,
        ref: inbound.kind === "message" ? inbound.message : inbound.action,
        activity: input.args.body,
    });
    if (session === undefined) {
        return skipped("unaddressed");
    }
    if (inbound.kind === "cardAction") {
        // Card actions skip the engagement gate, which is what admits allowlisted bots.
        if (inbound.action.author.isBot) {
            runtime.log(`warn ignoring a card click from Teams bot ${inbound.action.author.id} in ${inbound.action.conversation.id}`);
            return skipped("bot_sender");
        }
        const verdict = await senderVerdict({
            sender: inbound.action,
            address: inbound.address,
            tenantId: input.tenantId,
            runtime,
        });
        if (verdict !== "member") {
            runtime.log(`warn ignoring a card click from Teams sender ${inbound.action.author.id} in ${inbound.action.conversation.id}: ${verdict}`);
            return skipped(refusalReason(verdict));
        }
        return dispatchCardAction({
            ...input,
            action: inbound.action,
            address: inbound.address,
            session,
        });
    }
